$modelsToRemove = @(
    "deepseek-coder:33b-instruct-q4_K_M",
    "deepseek-coder:6.7b-instruct-q4_K_M",
    "yi-coder:9b-chat-q5_K_M",
    "qwen2.5-coder:1.5b-instruct-q4_K_M",
    "tinyllama:latest",
    "llava:latest"
)

foreach ($model in $modelsToRemove) {
    Write-Host "Removing model: $model"
    try {
        Invoke-RestMethod -Method Delete -Uri "http://localhost:11434/api/delete" -Body (@{name=$model} | ConvertTo-Json)
        Write-Host "Successfully removed $model"
    } catch {
        Write-Error "Failed to remove $model : $_"
    }
}

