17	
18	// â•â•â• TYPES â•â•â•
19	
20	export type RolodexProvider = 'ollama' | 'cloudflare' | 'gemini' | 'huggingface' | 'fireworks' | 'openrouter' | 'rsmv';
21	
22	export interface RolodexModel {
23	    id: string;
24	    name: string;
25	    provider: RolodexProvider;
26	    taskType: 'text' | 'image' | 'audio' | 'embedding' | 'vision' | 'unknown';
27	    parameterSize?: string;          // e.g. "14b", "7b"
28	    quantization?: string;           // e.g. "q5_K_M"
29	    lastSeen: number;                // epoch ms
30	    successCount: number;
31	    failureCount: number;
32	    totalTokensUsed: number;
33	    avgLatencyMs: number;
34	    latencySamples: number;
35	    reputation: number;             // 0.0 to 1.0 score
36	    isVision?: boolean;
37	    isText?: boolean;
38	    isEmbedding?: boolean;
39	}
40	
41	export interface ProviderIdentity {
42	    provider: RolodexProvider;
43	    authenticated: boolean;
44	    account?: string;
45	    email?: string;
46	    models: string[];
47	    latencyMs: number;
48	    lastChecked: number;
49	    error?: string;
50	}
51	
52	export interface RolodexState {
53	    models: Record<string, RolodexModel>;
54	    providers: Record<RolodexProvider, ProviderIdentity>;
55	    lastRefresh: number;
56	    version: string;
57	}
58	
59	// â•â•â• ROLODEX CORE â•â•â•
60	
61	/**
62	 * ModelRolodex â€” The Sovereign's Living Model Catalog.
63	 *
64	 * Dynamically discovers available models from each provider via API/shell calls.
65	 * Tracks per-model health (success/failure/latency/tokens).
66	 * Persists state to D:\sovereign
67	olodex.json for cross-session memory.
68	 * Ollama models are always the sovereign final fallback.
69	 */
70	export class ModelRolodex {
71	    private static instance?: ModelRolodex;
72	
73	    public static getInstance(): ModelRolodex | undefined {
74	        return ModelRolodex.instance;
75	    }
76	
77	    public state: RolodexState;
78	    private readonly persistPath: string;
79	    private refreshInProgress = false;
80	
81	    constructor(private readonly config: SovereignConfig) {
82	        ModelRolodex.instance = this;
83	        this.persistPath = join(config.pog2Dir || process.cwd(), 'rolodex.json');
84	
85	        // Attempt to load persisted state
86	        if (existsSync(this.persistPath)) {
87	            try {
88	                this.state = JSON.parse(readFileSync(this.persistPath, 'utf8'));
89	                logger.info({ models: Object.keys(this.state.models).length }, 'ðŸ—‚ï¸ Rolodex loaded from disk.');
90	
91	                // Phase 21: Reputation Healing - Restore baseline for unused/corrupted states
92	                for (const key in this.state.models) {
93	                    const m = this.state.models[key];
94	                    if (m.successCount === 0 && m.failureCount === 0 && m.reputation < 1.0) {
95	                        m.reputation = 1.0;
96	                    }
97	                    if (m.reputation < 0.2) {
98	                        m.reputation = 0.2; // Enforce absolute physiological floor
99	                    }
100	                }
101	            } catch {
102	                this.state = this.createEmptyState();
103	            }
104	        } else {
105	            this.state = this.createEmptyState();
106	        }
107	
108	        // Phase 9: Start Reputation Decay Interval
109	        const decayRate = config.reputationDecayRate || 0.05;
110	        // Interval: 1 hour in production, 1 minute in development/test
111	        const intervalMs = process.env.NODE_ENV === 'test' ? 60000 : 3600000;
112	        (setInterval(() => this.applyReputationDecay(decayRate), intervalMs) as any).unref();
113	    }
114	
115	    private createEmptyState(): RolodexState {
116	        const providers: Record<RolodexProvider, ProviderIdentity> = {
117	            ollama: { provider: 'ollama', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
118	            cloudflare: { provider: 'cloudflare', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
119	            gemini: { provider: 'gemini', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
120	            huggingface: { provider: 'huggingface', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
121	            fireworks: { provider: 'fireworks', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
122	            openrouter: { provider: 'openrouter', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
123	            rsmv: { provider: 'rsmv', authenticated: true, models: ['rsmv-substrate'], latencyMs: 0, lastChecked: Date.now() }
124	        };
125	        return { models: {}, providers, lastRefresh: 0, version: '1.0.0' };
126	    }
127	
128	    public getAllProviderStatuses(): Record<RolodexProvider, ProviderIdentity> {
129	        return this.state.providers;
130	    }
131	
132	    public getProviderStatus(provider: RolodexProvider): ProviderIdentity {
133	        return this.state.providers[provider];
134	    }
135	
136	
137	
138	    /** 
139	     * Sovereign FinOps / Hive Mind: Merge incoming state from the Globe substrate.
140	     * Aggregates success/failure counts instead of overwriting, allowing multiple 
141	     * instances to share learned reputation scores offline and online.
142	     */
143	    public deserializeAndMerge(remoteState: RolodexState): void {
144	        let mergedCount = 0;
145	
146	        // Merge Models (The Reputation Score)
147	        for (const [key, remoteModel] of Object.entries(remoteState.models)) {
148	            if (!this.state.models[key]) {
149	                this.state.models[key] = { ...remoteModel };
150	                mergedCount++;
151	            } else {
152	                const localModel = this.state.models[key];
153	                // Only aggregate if the remote state has actually seen usage
154	                if (remoteModel.successCount + remoteModel.failureCount > 0) {
155	                    // We don't want to double-count our own updates if they echo back.
156	                    // A true CRDT is better, but a simplistic Max(local, remote) or addition 
157	                    // works for basic reputation sharing until we build an event-sourced log.
158	                    // For now, if remote has higher total interaction, we absorb the difference.
159	                    const localTotal = localModel.successCount + localModel.failureCount;
160	                    const remoteTotal = remoteModel.successCount + remoteModel.failureCount;
161	
162	                    if (remoteTotal > localTotal) {
163	                        localModel.successCount = Math.max(localModel.successCount, remoteModel.successCount);
164	                        localModel.failureCount = Math.max(localModel.failureCount, remoteModel.failureCount);
165	                        localModel.totalTokensUsed = Math.max(localModel.totalTokensUsed, remoteModel.totalTokensUsed);
166	                        localModel.avgLatencyMs = Math.round((localModel.avgLatencyMs + remoteModel.avgLatencyMs) / 2);
167	                        mergedCount++;
168	                    }
169	                }
170	                // Always sync the lastSeen timestamp if remote is newer
171	                if (remoteModel.lastSeen > localModel.lastSeen) {
172	                    localModel.lastSeen = remoteModel.lastSeen;
173	                }
174	            }
175	        }
176	
177	        // Merge Providers (Auth status and discovered models)
178	        for (const [key, remoteIdentity] of Object.entries(remoteState.providers)) {
179	            const pKey = key as RolodexProvider;
180	            const localIdentity = this.state.providers[pKey];
181	
182	            // If remote is authenticated and we aren't, absorb their model list (but not their account/email/keys)
183	            // This allows an offline node to know what models exist on a provider even if it can't reach the discovery API.
184	            if (remoteIdentity.authenticated) {
185	                const newModels = remoteIdentity.models.filter(m => !localIdentity.models.includes(m));
186	                if (newModels.length > 0) {
187	                    localIdentity.models.push(...newModels);
188	                }
189	            }
190	        }
191	
192	        if (mergedCount > 0) {
193	            logger.debug({ mergedModels: mergedCount }, 'Rolodex merged state from Hive Mind');
194	            this.persist(); // Save to local disk immediately upon beneficial merge
195	        }
196	    }
197	
198	    // â•â•â• PUBLIC API â•â•â•
199	
200	    /** Get all models for a specific provider */
201	    getModelsForProvider(provider: RolodexProvider): RolodexModel[] {
202	        return Object.values(this.state.models).filter(m => m.provider === provider);
203	    }
204	
205	    /** Get all known models across all providers */
206	    getAllModels(): RolodexModel[] {
207	        return Object.values(this.state.models);
208	    }
209	
210	    /** Get provider identity & status */
211	
212	    // Add inside ModelRolodex class:
213	
214	    /**
215	     * Resolve capability tier to best healthy local model.
216	     * Checks health, reputation, walks fallback chain.
217	     */
218	    public resolveCapability(tier: string): { model: string; ctx: number; reputation: number } | null {
219	        const cap = getCapability(tier);
220	        if (!cap) return null;
221	
222	        // Preferred
223	        if (this.isModelHealthy(cap.preferredModel)) {
224	            const key = `ollama:${cap.preferredModel}`;
225	            const rep = this.state.models[key]?.reputation ?? 1.0;
226	            if (rep > 0.3) return { model: cap.preferredModel, ctx: cap.minCtx, reputation: rep };
227	        }
228	
229	        // Fallback chain
230	        for (const fb of cap.fallbackModels) {
231	            if (fb === cap.preferredModel) continue;
232	            if (this.isModelHealthy(fb)) {
233	                const key = `ollama:${fb}`;
234	                const rep = this.state.models[key]?.reputation ?? 0.5;
235	                if (rep > 0.2) {
236	                    logger.info({ tier, fallback: fb }, 'Capability fallback');
237	                    return { model: fb, ctx: cap.minCtx, reputation: rep };
238	                }
239	            }
240	        }
241	
242	        // Emergency: any healthy text model
243	        const emergency = this.getAllModels()
244	            .filter(m => m.provider === 'ollama' && m.taskType === 'text' && m.reputation > 0.2)
245	            .sort((a, b) => b.reputation - a.reputation)[0];
246	
247	        if (emergency) {
248	            logger.warn({ tier, emergency: emergency.id }, 'Emergency fallback');
249	            return { model: emergency.id, ctx: 4096, reputation: emergency.reputation };
250	        }
251	
252	        return null;
253	    }
254	
255	    /**
256	     * If modelOrTier is a capability name, resolve it. Otherwise pass through.
257	     */
258	    public resolveModelOrCapability(modelOrTier: string): { model: string; ctx: number; isCapability: boolean; reputation: number } {
259	        if (isCapabilityTier(modelOrTier)) {
260	            const resolved = this.resolveCapability(modelOrTier);
261	            if (resolved) return { ...resolved, isCapability: true };
262	        }
263	        return {
264	            model: modelOrTier,
265	            ctx: 4096,
266	            isCapability: false,
267	            reputation: this.state.models[`ollama:${modelOrTier}`]?.reputation ?? 1.0
268	        };
269	    }
270	
271	    /** Check if ALL cloud providers are down (triggers sovereign Ollama override) */
272	    isAllCloudDown(): boolean {
273	        const cloudProviders: RolodexProvider[] = ['cloudflare', 'gemini', 'huggingface', 'fireworks', 'openrouter'];
274	        return cloudProviders.every(p => {
275	            const status = this.state.providers[p];
276	            // Consider "down" if: not authenticated, or has an error, or last checked > 5 min ago and no models
277	            return !status.authenticated || !!status.error || (status.models.length === 0 && status.lastChecked > 0);
278	        });
279	    }
280	
281	    /** Check if Ollama is alive */
282	    isOllamaAlive(): boolean {
283	        const status = this.state.providers.ollama;
284	        return status.authenticated && status.models.length > 0;
285	    }
286	
287	    /** Check if a specific model is healthy and available */
288	    isModelHealthy(modelId: string): boolean {
289	        // 1. Identify provider
290	        let provider: RolodexProvider = 'ollama';
291	        let id = modelId;
292	
293	        if (modelId.includes(':')) {
294	            const parts = modelId.split(':');
295	            provider = ModelRolodex.toRolodexProvider(parts[0]);
296	            id = parts.slice(1).join(':');
297	        }
298	
299	        // 2. Check provider state
300	        const status = this.state.providers[provider];
301	        if (!status || !status.authenticated || !!status.error) return false;
302	
303	        // 3. Check if model exists in discovered list
304	        if (!status.models.includes(id)) return false;
305	
306	        // 4. Check reputation floor (Phase 108: 0.2 floor)
307	        const key = `${provider}:${id}`;
308	        const model = this.state.models[key];
309	        if (model && model.reputation < 0.2) return false;
310	
311	        return true;
312	    }
313	
314	    /** Get best available models for a failover sequence, sorted by learned reputation. */
315	    getHealthyModelsByTaskType(taskType: 'text' | 'image' | 'audio' | 'embedding' | 'vision'): string[] {
316	        const allModels = this.getAllModels();
317	
318	        // Filter by task type and sort by learned reputation
319	        const scored = allModels
320	            .filter(m => m.taskType === taskType)
321	            .sort((a, b) => b.reputation - a.reputation);
322	
323	        return scored.map(m => `${m.provider}:${m.id}`);
324	    }
325	
326	    /** Record a model call result (called by ModelClient after each call) */
327	    recordCallResult(model: string, provider: RolodexProvider, success: boolean, latencyMs: number, tokensUsed?: number): void {
328	        const key = `${provider}:${model}`;
329	        if (!this.state.models[key]) {
330	            this.state.models[key] = {
331	                id: model,
332	                name: model,
333	                provider,
334	                taskType: 'text',
335	                lastSeen: Date.now(),
336	                successCount: 0,
337	                failureCount: 0,
338	                totalTokensUsed: 0,
339	                avgLatencyMs: 0,
340	                latencySamples: 0,
341	                reputation: 1.0,
342	                isText: true // Default
343	            };
344	        }
345	
346	        const entry = this.state.models[key];
347	        if (success) {
348	            entry.successCount++;
349	        } else {
350	            entry.failureCount++;
351	        }
352	        entry.lastSeen = Date.now();
353	        entry.totalTokensUsed += tokensUsed || 0;
354	
355	        // Rolling average latency
356	        entry.latencySamples++;
357	        entry.avgLatencyMs = entry.avgLatencyMs + (latencyMs - entry.avgLatencyMs) / entry.latencySamples;
358	
359	        // ðŸ§¬ Update reputation score
360	        entry.reputation = this.computeReputation(entry);
361	
362	        // Persist periodically (every 10 calls)
363	        const totalInteractions = entry.successCount + entry.failureCount;
364	        if (totalInteractions % 10 === 0) {
365	            this.persist();
366	        }
367	
368	        // Global Reputation Decay is now handled by an interval
369	    }
370	
371	    /** ðŸ§¬ Evolutionary Mutation - Manually adjust reputation based on strategy advisor */
372	    public mutateReputation(modelId: string, provider: RolodexProvider, adjustment: number): void {
373	        const key = `${provider}:${modelId}`;
374	        const entry = this.state.models[key];
375	        if (!entry) return;
376	
377	        const oldRep = entry.reputation;
378	        // ðŸ§¬ Phase 108: Physiological clamping (Prevent drift chaos)
379	        entry.reputation = Math.max(0.2, Math.min(2.0, entry.reputation + adjustment));
380	
381	        logger.info({
382	            model: modelId,
383	            provider,
384	            oldRep: oldRep.toFixed(4),
385	            newRep: entry.reputation.toFixed(4),
386	            adjustment
387	        }, 'ðŸ§¬ Model reputation mutated by strategy advisor.');
388	
389	        this.persist();
390	    }
391	
392	    /** ðŸ§¬ Reputation Scoring Algorithm - Research Grade */
393	    private computeReputation(m: RolodexModel): number {
394	        const totalCalls = m.successCount + m.failureCount;
395	        if (totalCalls === 0) return 1.0;
396	
397	        // 1. Success Rate Component (60%)
398	        const successRate = m.successCount / totalCalls;
399	
400	        // 2. Latency Component (30%) - Normalized (0.1 effectively infinite, 1.0 instant)
401	        // Assume 50ms is "instant" and 5000ms is "stalled"
402	        const latencyFactor = Math.max(0, 1 - (m.avgLatencyMs / 5000));
403	
404	        // 3. Cost/Token Penalty (10%) - Discourage massive token burns without success
405	        const tokenPenalty = Math.min(0.1, (m.totalTokensUsed / 1_000_000) * 0.1);
406	
407	        const score = (successRate * 0.6) + (latencyFactor * 0.3) + 0.1 - tokenPenalty;
408	        // ðŸ§¬ Phase 108: Clamping to physiological bounds (0.2 to 2.0)
409	        return Math.max(0.2, Math.min(2.0, score));
410	    }
411	
412	    // â•â•â• DISCOVERY â•â•â•
413	
414	    /** Refresh all providers â€” non-blocking, fire-and-forget safe */
415	    async refreshAll(): Promise<void> {
416	        if (this.refreshInProgress) {
417	            logger.info('Rolodex refresh already in progress, skipping.');
418	            return;
419	        }
420	        this.refreshInProgress = true;
421	        logger.info('ðŸ”„ Rolodex: Refreshing all provider models...');
422	
423	        const start = Date.now();
424	        await Promise.allSettled([
425	            this.discoverOllama(),
426	            this.discoverCloudflare(),
427	            this.discoverGemini(),
428	            this.discoverHuggingFace(),
429	            this.discoverOpenRouter(),
430	            this.discoverFireworks()
431	        ]);
432	
433	        this.state.lastRefresh = Date.now();
434	        this.refreshInProgress = false;
435	        this.persist();
436	
437	        const modelCount = Object.keys(this.state.models).length;
438	        const elapsed = Date.now() - start;
439	        logger.info({ modelCount, elapsed }, 'âœ… Rolodex refresh complete.');
440	    }
441	
442	    /** Discover Ollama models via REST API */
443	    private async discoverOllama(): Promise<void> {
444	        const start = Date.now();
445	        const providerState = this.state.providers.ollama;
446	        try {
447	            const baseUrl = this.config.ollamaBaseUrl || 'http://localhost:11434';
448	            // Increase timeout to 60s for massive substrates
449	            const response = await undiciFetch(`${baseUrl}/api/tags`, { signal: AbortSignal.timeout(120000) });
450	            if (!response.ok) throw new Error(`Ollama API returned ${response.status}`);
451	
452	            const data = await response.json() as { models?: { name: string; size?: number; details?: { parameter_size?: string; quantization_level?: string; family?: string } }[] };
453	            const models = data.models || [];
454	
455	            providerState.authenticated = true;
456	            providerState.models = models.map(m => m.name);
457	            providerState.latencyMs = Date.now() - start;
458	            providerState.lastChecked = Date.now();
459	            providerState.error = undefined;
460	
461	            for (const m of models) {
462	                const key = `ollama:${m.name}`;
463	                if (!this.state.models[key]) {
464	                    this.state.models[key] = {
465	                        id: m.name,
466	                        name: m.name,
467	                        provider: 'ollama',
468	                        taskType: m.name.includes('embed') ? 'embedding' : m.name.includes('llava') || m.name.includes('moondream') ? 'vision' : m.name.includes('audio') || m.name.includes('whisper') ? 'audio' : m.name.includes('image') || m.name.includes('draw') ? 'image' : 'text',
469	                        parameterSize: m.details?.parameter_size,
470	                        quantization: m.details?.quantization_level,
471	                        lastSeen: Date.now(),
472	                        successCount: 0, failureCount: 0, totalTokensUsed: 0, avgLatencyMs: 0,
473	                        latencySamples: 0,
474	                        reputation: 1.0,
475	                        isEmbedding: m.name.includes('embed'),
476	                        isVision: m.name.includes('llava') || m.name.includes('moondream'),
477	                        isText: !m.name.includes('embed')
478	                    };
479	                } else {
480	                    this.state.models[key].lastSeen = Date.now();
481	                    this.state.models[key].parameterSize = m.details?.parameter_size ?? this.state.models[key].parameterSize;
482	                }
483	            }
484	
485	            logger.info({ count: models.length }, 'Ollama models discovered.');
486	        } catch (err: any) {
487	            // For timeouts: Preserve authentication and model list if we already have data
488	            const isTimeout = err.name === 'TimeoutError' || err.message.includes('timeout') || err.message.includes('aborted');
489	
490	            if (isTimeout && providerState.models.length > 0) {
491	                logger.warn({ error: err.message, cachedModels: providerState.models.length }, 'Ollama discovery timed out. Preserving cached model state.');
492	                providerState.error = `DISCOVERY_TIMEOUT: ${err.message}`; // Mark as busy/timeout but keep authenticated
493	            } else {
494	                providerState.authenticated = false;
495	                providerState.error = err.message;
496	                logger.warn({ error: err.message }, 'Ollama discovery failed.');
497	            }
498	
499	            providerState.latencyMs = Date.now() - start;
500	            providerState.lastChecked = Date.now();
501	        }
502	    }
503	
504	    /** 
505	     * Discover Cloudflare models via REST API 
506	     * // NOTE: If ModelClient fails to actuate a dynamically chosen Cloudflare model (e.g., Llama)
507	     * // with a 403 or TOS error, you MUST manually run `npx wrangler ai run <model-tag>` 
508	     * // in the terminal to accept the Cloudflare AI Terms of Service for that specific model.
509	     */
510	    private async discoverCloudflare(): Promise<void> {
511	        const start = Date.now();
512	        const providerState = this.state.providers.cloudflare;
513	
514	        if (!this.config.cloudflareAccountId || !this.config.cloudflareApiToken) {
515	            providerState.error = 'Missing CLOUDFLARE_ACCOUNT_ID or CLOUDFLARE_API_TOKEN';
516	            providerState.lastChecked = Date.now();
517	            return;
518	        }
519	
520	        try {
521	            // Identity check via wrangler whoami (direct execution)
522	            const { stdout: whoami } = await $`wrangler whoami 2>&1`;
523	            const accountMatch = whoami.match(/Account ID:\s*(\S+)/i) || whoami.match(/(\w{32})/);
524	            const emailMatch = whoami.match(/Email:\s*(\S+)/i) || whoami.match(/[\w.-]+@[\w.-]+\.\w+/);
525	
526	            providerState.authenticated = whoami.toLowerCase().includes('logged in') || !!accountMatch;
527	            providerState.account = accountMatch?.[1] || this.config.cloudflareAccountId;
528	            providerState.email = emailMatch?.[0] || this.config.cloudflareAuthEmail;
529	
530	            // Model discovery via REST API
531	            const cfApiUrl = `https://api.cloudflare.com/client/v4/accounts/${this.config.cloudflareAccountId}/ai/models/search`;
